document.querySelectorAll("#report-metric-order,#safety-metric-order").forEach(list=>list.addEventListener("click",function(e){const b=e.target.closest("button");if(!b)return;const li=b.closest("li");if(b.classList.contains("report-up")&&li.previousElementSibling)li.parentElement.insertBefore(li,li.previousElementSibling);if(b.classList.contains("report-down")&&li.nextElementSibling)li.parentElement.insertBefore(li.nextElementSibling,li);}));
